/* Dated historical expeditions; their scores never alter modern country progress. */
(function(){
'use strict';
const shuffle=(items,random=Math.random)=>{const out=items.slice();for(let i=out.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return out};
function makeSession(places,random=Math.random){return {deck:shuffle(places,random),cursor:0,results:[]}}
function answerSession(session,id){if(session.cursor>=session.deck.length||session.results[session.cursor])return null;const target=session.deck[session.cursor],result={id:target.id,guess:id,correct:id===target.id};session.results.push(result);return result}
function advanceSession(session){if(session.results[session.cursor])session.cursor++;return session.cursor>=session.deck.length}
if(typeof document==='undefined'){module.exports={shuffle,makeSession,answerSession,advanceSession};return}
const el=id=>document.getElementById(id),root=el('historicalExperience');let data=null,era='roman',session=null,places=[],historyMap=null,mapReady=false,open=false,hidden=[],timer=0,hold=0,held=null,busy=false,request=0;
const study=()=>el('historyMode').value==='study';const dark=()=>el('historyTheme').value==='dark';const target=()=>session.deck[session.cursor];const done=()=>session.cursor>=session.deck.length;const answered=()=>!!session.results[session.cursor];
function cancelTimers(){clearTimeout(timer);timer=0;clearTimeout(hold);hold=0;held=null;root.classList.remove('history-holding')}
function feedback(text){el('historyFeedback').textContent=text}
function count(){return session.results.filter(r=>r.correct).length}
function fit(){if(mapReady)historyMap.fitBounds([[-12,24],[43,59]],{padding:{left:window.innerWidth>700?325:24,right:55,top:window.innerWidth>700?40:350,bottom:70},duration:0})}
function facts(p){el('historyFacts').hidden=false;el('historyFactKind').textContent=p.kind+' · '+data[era].date;el('historyFactTitle').textContent=p.name;el('historyFactModern').textContent='Present-day orientation: '+p.modern;el('historyFactBody').textContent=p.fact;el('historyFactSource').href=p.source}
function mapData(){return {type:'FeatureCollection',features:places.map((p,i)=>({type:'Feature',properties:{id:p.id,number:String(i+1),name:p.name,kind:p.kind},geometry:{type:'Point',coordinates:p.center}}))}}
function paint(){if(!mapReady||!session)return;const aged=!dark(),ink=aged?'#4f3a23':'#f1e3c0',ocean=aged?'#c7b381':'#15252c',land=aged?'#e6d4a4':'#465148';historyMap.setPaintProperty('history-ocean','background-color',ocean);historyMap.setPaintProperty('history-land','fill-color',land);historyMap.setPaintProperty('history-coast','line-color',aged?'#7d6944':'#9c9d82');historyMap.setPaintProperty('history-extent','fill-color',aged?'#a65c40':'#a56d58');historyMap.setPaintProperty('history-extent','fill-opacity',.28);for(const id of ['history-extent','history-extent-line'])historyMap.setLayoutProperty(id,'visibility',era==='roman'?'visible':'none');historyMap.getSource('history-points').setData(mapData());const result=session.results[session.cursor],right=result?.id||'',wrong=result&&!result.correct?result.guess||'':'';historyMap.setPaintProperty('history-markers','circle-color',['case',['==',['get','id'],right],aged?'#f8efd2':'#f8e6ac',['==',['get','id'],wrong],'#b67b63',aged?'#9d7138':'#b9a16a']);historyMap.setPaintProperty('history-markers','circle-stroke-color',['case',['==',['get','id'],right],ink,aged?'#f0e0b7':'#26332f']);historyMap.setPaintProperty('history-markers','circle-stroke-width',['case',['==',['get','id'],right],3,1.5]);historyMap.setPaintProperty('history-numbers','text-color',aged?'#fff5d8':'#18272a');historyMap.setPaintProperty('history-names','text-color',ink);historyMap.setPaintProperty('history-names','text-halo-color',land);historyMap.setFilter('history-names',study()?['has','id']:['==',['get','id'],right]);historyMap.setLayoutProperty('history-names','visibility',study()||result?'visible':'none')}
function render(){if(!session)return;root.classList.toggle('history-dark',dark());root.classList.toggle('history-study',study());el('historyTitle').textContent=data[era].title;el('historyDate').textContent=data[era].date;el('historyIntro').textContent=data[era].intro;el('historyNote').textContent=data[era].note;el('historyMapCaption').textContent=era==='roman'?'RUSSET · ROMAN EXTENT, AD 117':'REPRESENTATIVE PLACES · c. AD 1200';el('historyRound').textContent=study()?'UNSCORED STUDY · '+places.length+' PLACES':done()?'EXPEDITION COMPLETE':`PLACE ${session.cursor+1} / ${session.deck.length}`;el('historyKind').textContent=study()?'Explore the map':done()?'Your historical atlas':target().kind;el('historyQuestion').textContent=study()?'Every place has a story.':done()?(count()===session.deck.length?'An age well known.':'History, a little closer.'):target().name;el('historyInstruction').textContent=study()?'Select a named marker or a place below to read its history.':done()?'Start a new expedition to take another route through this era.':(typeof answerGesture!=='undefined'&&answerGesture==='hold'?'Press and hold':'Tap')+' the numbered marker for this place.';el('historyScore').textContent=study()?data[era].scope:`${count()} / ${session.deck.length} correct`;el('historySkip').hidden=study()||done()||answered();const choices=el('historyChoices');choices.replaceChildren();for(const [i,p]of places.entries()){const button=document.createElement('button');button.type='button';button.textContent=study()?`${i+1} · ${p.name}`:String(i+1);button.setAttribute('aria-label',study()?p.name:`Historical location ${i+1}`);button.onclick=e=>{if(e.detail===0||typeof answerGesture==='undefined'||answerGesture!=='hold')select(p.id)};button.onpointerdown=e=>beginHold(e,p.id);button.onpointerup=button.onpointercancel=clearHold;button.onpointermove=moveHold;choices.append(button)}paint()}
function clearHold(){clearTimeout(hold);hold=0;held=null;root.classList.remove('history-holding')}
function beginHold(e,id){if(study()||typeof answerGesture==='undefined'||answerGesture!=='hold')return;if(e.isPrimary===false){clearHold();return}clearHold();held={x:e.clientX,y:e.clientY};root.classList.add('history-holding');hold=setTimeout(()=>{clearHold();select(id)},650)}
function moveHold(e){if(held&&Math.hypot(e.clientX-held.x,e.clientY-held.y)>10)clearHold()}
function select(id){const p=places.find(p=>p.id===id);if(!p||!open)return;if(study()){facts(p);return}const result=answerSession(session,id);if(!result)return;cancelTimers();facts(target());feedback(result.correct?'✓ Correct · Moving on…':`${target().name} is outlined on the map · Moving on…`);if(typeof playUiSound==='function')playUiSound(result.correct?'correct':'miss');render();timer=setTimeout(next,result.correct?900:2400)}
function skip(){if(!session||done()||study())return;const result=answerSession(session,null);if(!result)return;cancelTimers();facts(target());feedback(target().name+' is outlined on the map · Moving on…');render();timer=setTimeout(next,2400)}
function next(){cancelTimers();if(!open||study()||!session)return;advanceSession(session);el('historyFacts').hidden=true;feedback('');if(done()){try{const key='atlas-history-best-'+era+'-'+el('historyScope').value,best=Math.max(Number(localStorage.getItem(key))||0,Math.round(count()/session.deck.length*100));localStorage.setItem(key,String(best));feedback(`Personal best: ${best}% · Historical progress is saved separately.`)}catch{}if(typeof playUiSound==='function')playUiSound('complete')}render()}
function restart(){if(!data)return;cancelTimers();const scope=el('historyScope').value;places=data[era].places.filter(p=>scope==='all'||(scope==='cities'?p.kind==='City':p.kind!=='City'));session=makeSession(places);el('historyFacts').hidden=true;feedback('');render();fit()}
async function setupMap(){if(historyMap){historyMap.resize();fit();return}historyMap=new mapboxgl.Map({container:'historyMap',style:{version:8,glyphs:'mapbox://fonts/mapbox/{fontstack}/{range}.pbf',sources:{},layers:[{id:'history-ocean',type:'background',paint:{'background-color':'#c7b381'}}]},center:[14,40],zoom:2.7,minZoom:1.5,maxZoom:8,scrollZoom:false,cooperativeGestures:false,doubleClickZoom:false,dragRotate:false,attributionControl:false});historyMap.addControl(new mapboxgl.AttributionControl({compact:true,customAttribution:'Base: Natural Earth · Roman extent: AWMC / ODbL'}));historyMap.on('load',()=>{historyMap.addSource('history-world',{type:'geojson',data:'world.geojson'});historyMap.addLayer({id:'history-land',type:'fill',source:'history-world',paint:{'fill-color':'#e6d4a4'}});historyMap.addLayer({id:'history-coast',type:'line',source:'history-world',paint:{'line-color':'#7d6944','line-width':.6,'line-opacity':0}});historyMap.addSource('history-rome',{type:'geojson',data:'roman-empire-117.geojson'});historyMap.addLayer({id:'history-extent',type:'fill',source:'history-rome',paint:{'fill-color':'#a65c40','fill-opacity':.28}});historyMap.addLayer({id:'history-extent-line',type:'line',source:'history-rome',paint:{'line-color':'#874a33','line-width':1.2,'line-opacity':0}});historyMap.addSource('history-points',{type:'geojson',data:mapData()});historyMap.addLayer({id:'history-markers',type:'circle',source:'history-points',paint:{'circle-radius':['interpolate',['linear'],['zoom'],1.5,8,4,13,7,17],'circle-color':'#9d7138','circle-stroke-color':'#f0e0b7','circle-stroke-width':1.5}});historyMap.addLayer({id:'history-numbers',type:'symbol',source:'history-points',layout:{'text-field':['get','number'],'text-font':['Open Sans Semibold','Arial Unicode MS Regular'],'text-size':12,'text-allow-overlap':true},paint:{'text-color':'#fff5d8'}});historyMap.addLayer({id:'history-names',type:'symbol',source:'history-points',layout:{'text-field':['get','name'],'text-font':['Open Sans Regular','Arial Unicode MS Regular'],'text-size':13,'text-anchor':'top','text-offset':[0,1.1],'text-max-width':9,'text-padding':4,'text-variable-anchor':['top','bottom','left','right']},paint:{'text-color':'#4f3a23','text-halo-color':'#e6d4a4','text-halo-width':1.5}});mapReady=true;historyMap.on('click',e=>{if(typeof answerGesture!=='undefined'&&answerGesture==='hold'&&!study())return;const f=historyMap.queryRenderedFeatures(e.point,{layers:['history-markers']})[0];if(f)select(f.properties.id)});const canvas=historyMap.getCanvas();canvas.addEventListener('pointerdown',e=>{if(e.isPrimary===false){clearHold();return}const rect=canvas.getBoundingClientRect(),f=historyMap.queryRenderedFeatures({x:e.clientX-rect.left,y:e.clientY-rect.top},{layers:['history-markers']})[0];if(f)beginHold(e,f.properties.id)});canvas.addEventListener('pointermove',moveHold);for(const type of ['pointerup','pointercancel','pointerleave'])canvas.addEventListener(type,clearHold);canvas.addEventListener('contextmenu',e=>{if(typeof answerGesture!=='undefined'&&answerGesture==='hold')e.preventDefault()});historyMap.on('dragstart',clearHold);paint();fit()});historyMap.on('error',()=>{el('historyError').hidden=false;el('historyError').textContent='Part of the historical map could not load. Check your connection and try again.'})}
async function show(which){if(busy)return;busy=true;const token=++request;try{if(!data){const r=await fetch('historical.json?v=20261031');if(!r.ok)throw Error('Historical places unavailable');data=await r.json()}if(token!==request)return;era=which;el('historyEra').value=era;if(typeof cancelAdvance==='function')cancelAdvance();if(typeof setMapActive==='function')setMapActive(false);hidden=[...document.querySelectorAll('.collection,.game-layout,#countryFacts,.stats,#review,#profileDialog')].map(node=>[node,node.hidden]);for(const [node]of hidden)node.hidden=true;open=true;root.hidden=false;restart();await setupMap();root.scrollIntoView({behavior:'instant',block:'start'})}catch(e){el(which==='roman'?'romanOpen':'medievalOpen').textContent='Retry historical atlas';console.error(e)}finally{busy=false}}
function close(){request++;cancelTimers();root.hidden=true;open=false;for(const [node,value]of hidden)node.hidden=value;if(typeof setMapActive==='function')setMapActive(true);if(typeof scheduleAdvance==='function')scheduleAdvance();document.querySelector('.collection').scrollIntoView({behavior:'instant',block:'start'})}
el('romanOpen').onclick=()=>show('roman');el('medievalOpen').onclick=()=>show('medieval');el('historyClose').onclick=close;el('historyEra').onchange=()=>{era=el('historyEra').value;restart()};el('historyMode').onchange=restart;el('historyScope').onchange=restart;el('historyTheme').onchange=render;el('historyRestart').onclick=restart;el('historySkip').onclick=skip;el('historyZoomIn').onclick=()=>historyMap?.zoomIn();el('historyZoomOut').onclick=()=>historyMap?.zoomOut();el('historyReset').onclick=fit;
for(const button of document.querySelectorAll('header button,header a'))button.addEventListener('click',()=>{if(open)close()},true);
document.addEventListener('visibilitychange',()=>{if(!open||study())return;if(document.hidden)cancelTimers();else if(session&&!done()&&answered())timer=setTimeout(next,1200)});
})();
